// Cafemutual: pulls Industry + Insurance article links from the archive page HTML.
const decode = s => String(s || '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#0?39;|&apos;|&#x27;/g, "'")
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ')
  .replace(/&[lr]squo;/g, "'").replace(/&[lr]dquo;/g, '"').replace(/&ndash;/g, '-').replace(/&mdash;/g, '-').replace(/&hellip;/g, '...')
  .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCharCode(parseInt(h, 16)))
  .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(n))
  .replace(/\s+/g, ' ').trim();

const PATTERN = /^https:\/\/cafemutual\.com\/news\/(industry|insurance)\/\d+-/;   // sections to keep
const d = $input.first()?.json?.data;
const html = typeof d === 'string' ? d : '';
const out = new Map();

const aTag = /<a\b([^>]*)>([\s\S]*?)<\/a>/gi;
let m;
while ((m = aTag.exec(html)) !== null) {
  const href = (m[1].match(/href\s*=\s*["']([^"']+)["']/i) || [])[1];
  if (!href) continue;
  let url = href.trim().replace(/&amp;/g, '&');
  if (url.startsWith('/')) url = 'https://cafemutual.com' + url;
  url = url.split('#')[0].split('?')[0];
  const pm = url.match(PATTERN);
  if (!pm) continue;
  const titleAttr = decode((m[1].match(/title\s*=\s*["']([^"']+)["']/i) || [])[1]);
  const text = decode(m[2]);
  const title = text.length >= titleAttr.length ? text : titleAttr;
  if (title.length < 15) continue;
  const prev = out.get(url);
  if (!prev || title.length > prev.title.length) out.set(url, { source: 'cafemutual', section: pm[1], url, title });
}
return [...out.values()].map(a => ({ json: a }));

// Moneycontrol RSS feeds. Replace any URL that errors with the feed URLs you used before.
const feeds = [
  { section: 'economy',          url: 'https://www.moneycontrol.com/rss/economy.xml' },
  { section: 'mutual-funds',     url: 'https://www.moneycontrol.com/rss/mfnews.xml' },
  { section: 'personal-finance', url: 'https://www.moneycontrol.com/rss/personalfinance.xml' },
  { section: 'world',            url: 'https://www.moneycontrol.com/rss/internationalmarkets.xml' },
  { section: 'markets',          url: 'https://www.moneycontrol.com/rss/marketreports.xml' },
];
return feeds.map(f => ({ json: f }));

// Moneycontrol: maps RSS Read output to the common article shape. Failed feeds are skipped.
const feeds = $('MC Feeds').all();
const out = new Map();
for (const item of $input.all()) {
  const j = item.json;
  if (j.error || !j.title || !j.link) continue;
  const feed = feeds[item.pairedItem?.item ?? 0]?.json || {};
  const url = String(j.link).trim().split('#')[0].split('?')[0];
  const title = String(j.title).replace(/\s+/g, ' ').trim();
  if (title.length < 15) continue;
  out.set(url, { source: 'moneycontrol', section: feed.section || 'rss', url, title });
}
return [...out.values()].map(a => ({ json: a }));

// CNBC TV18 RSS feeds. market.xml is confirmed; the others follow the same URL pattern and are skipped if they fail.
// Check the RSS link in cnbctv18.com's footer and replace/add URLs as needed.
const feeds = [
  { section: 'market',   url: 'https://www.cnbctv18.com/commonfeeds/v1/cne/rss/market.xml' },
  { section: 'economy',  url: 'https://www.cnbctv18.com/commonfeeds/v1/cne/rss/economy.xml' },
  { section: 'business', url: 'https://www.cnbctv18.com/commonfeeds/v1/cne/rss/business.xml' },
  { section: 'world',    url: 'https://www.cnbctv18.com/commonfeeds/v1/cne/rss/world.xml' },
];
return feeds.map(f => ({ json: f }));

// CNBC TV18: maps RSS Read output to the common article shape. Failed feeds are skipped.
const feeds = $('CNBC Feeds').all();
const out = new Map();
for (const item of $input.all()) {
  const j = item.json;
  if (j.error || !j.title || !j.link) continue;
  const feed = feeds[item.pairedItem?.item ?? 0]?.json || {};
  const url = String(j.link).trim().split('#')[0].split('?')[0];
  const title = String(j.title).replace(/\s+/g, ' ').trim();
  if (title.length < 15) continue;
  out.set(url, { source: 'cnbctv18', section: feed.section || 'rss', url, title });
}
return [...out.values()].map(a => ({ json: a }));

// First matching rule by priority wins. Builds one bulk INSERT; existing URLs are skipped.
const rules = $input.all().map(r => r.json)
  .filter(r => r.pattern)
  .sort((a, b) => a.priority - b.priority)
  .map(r => ({ category: r.category, source: r.source || null, re: new RegExp(r.pattern, r.case_sensitive ? '' : 'i') }));

const articles = $('Merge').all().map(a => a.json).filter(a => a.url && a.title);
if (!articles.length) return [];

const q = v => `'${String(v).replace(/'/g, "''")}'`;
const rows = articles.map(a => {
  const hit = rules.find(r => (!r.source || r.source === a.source) && r.re.test(a.title));
  const category = hit ? hit.category : 'uncategorised';
  return `(${q(a.url)}, ${q(a.source)}, ${q(a.section)}, ${q(a.title)}, ${q(category)})`;
});

const sql = `INSERT INTO articles (url, source, section, title, category) VALUES\n${rows.join(',\n')}\nON CONFLICT (url) DO NOTHING;`;
return [{ json: { sql, scanned: articles.length } }];
